#define N 512
int matrix[N][N];

// Case A: Row-Major (Excellent Spatial Locality)
// Sequential memory access maximizes cache line utilization
void access_rows() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] += 1;
        }
    }
}

// Case B: Column-Major (Poor Spatial Locality)
// Large strides (N * sizeof(int)) cause frequent cache misses
void access_cols() {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            matrix[i][j] += 1;
        }
    }
}
